#include <vector>
using namespace std;

const long long MOD = 10000019;

long long addMod(long long a, long long b) {
    return (a + b) % MOD;
}

long long mulMod(long long a, long long b) {
    return (a * b) % MOD;
}

int countBalancedSelections(const vector<vector<int>>& grid) {
    int N = (int)grid.size();
    int M = (int)grid[0].size();
    vector<int> A(M, 0);
    for (int col = 0; col < M; ++col) {
        for (int row = 0; row < N; ++row) {
            A[col] += grid[row][col];
        }
    }
    // Precompute combinations up to N
    vector<vector<long long>> C(N + 1, vector<long long>(N + 1, 0));
    for (int i = 0; i <= N; ++i) {
        C[i][0] = C[i][i] = 1;
        for (int j = 1; j < i; ++j) {
            C[i][j] = addMod(C[i-1][j-1], C[i-1][j]);
        }
    }
    vector<vector<long long>> dp(M + 1, vector<long long>(N + 1, 0));
    dp[0][0] = 1;
    for (int x = 1; x <= M; ++x) {
        int a = A[x-1];
        for (int k = 0; k <= N; ++k) {
            if (dp[x-1][k] == 0) continue;
            for (int i = 0; i <= a; ++i) {
                if (i > N - k) continue;
                if (a - i > k) continue;
                int nextK = k + (2*i - a);
                if (nextK < 0 || nextK > N) continue;
                long long ways = mulMod(C[N-k][i], C[k][a-i]);
                dp[x][nextK] = addMod(dp[x][nextK], mulMod(dp[x-1][k], ways));
            }
        }
    }
    return (int)dp[M][0];
}

